const state = { mode: 'loading', user: null, clients: {}, clientKey: null, projectKey: null, tab: 'overview', token: null, publicClient: null, artifacts: { signatures: {}, confirms: {} }, feedback: {} };

function esc(value = '') { return String(value).replace(/[&<>'"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[c])); }
function text(value = '') { return String(value ?? '').trim(); }
function safeHttpUrl(value = '') { try { const url = new URL(String(value)); return ['https:', 'http:'].includes(url.protocol) ? url.href : ''; } catch { return ''; } }
function safeSignatureImage(value = '') { return /^data:image\/png;base64,/i.test(String(value)) ? String(value) : ''; }
function money(value = 0) { return `৳${Number(value || 0).toLocaleString()}`; }
function dateNow() { return new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }); }
function token() { const bytes = new Uint8Array(24); crypto.getRandomValues(bytes); return [...bytes].map(n => n.toString(16).padStart(2, '0')).join(''); }
function approvalId(approval, index) { return approval.id || `legacy-${index}`; }
function itemStatus(item) { return STATUS.includes(item?.s) ? item.s : 'pending'; }
function isDone(item) { return ['completed', 'delivered'].includes(itemStatus(item)); }
function projectItems(project) { return Array.isArray(project?.items) ? project.items : []; }
function projectTotal(project) { return Number(project?.totalItems || projectItems(project).length || 0); }
function progress(project) { const total = projectTotal(project); const done = projectItems(project).filter(isDone).length; return { total, done, percent: total ? Math.round(done / total * 100) : 0 }; }
function currentClient() { return state.mode === 'client' ? state.publicClient : state.clients[state.clientKey]; }
function currentProject() { return currentClient()?.projects?.[state.projectKey]; }
function keyFor(...parts) { return parts.join('::'); }

let toastTimer;
function toast(message, type = 'ok') { const node = $('toast'); node.textContent = message; node.className = `toast ${type === 'error' ? 'error' : ''} show`; clearTimeout(toastTimer); toastTimer = setTimeout(() => node.className = 'toast', 3500); }
function friendlyError(error) { const code = error?.code || ''; if (code.includes('permission-denied')) return 'Permission denied. Check the portal security rules.'; if (code.includes('network')) return 'Network connection failed. Please try again.'; if (code.includes('invalid-credential')) return 'Email or password is incorrect.'; return error?.message || 'Something went wrong. Please try again.'; }
async function safely(work) { try { await work(); } catch (error) { console.error(error); toast(friendlyError(error), 'error'); } }
function setHeader() {
  if (state.mode === 'admin') topActions.innerHTML = '<span class="badge active">Admin</span><button class="button ghost" data-action="dashboard">Dashboard</button><button class="button" data-action="logout">Sign out</button>';
  else if (state.mode === 'client') topActions.innerHTML = '<span class="badge completed">Private client view</span>';
  else topActions.innerHTML = '';
}
function setUrl() {
  const q = new URLSearchParams();
  if (state.mode === 'client' && state.token) q.set('access', state.token);
  if (state.projectKey) q.set('p', state.projectKey);
  if (state.mode === 'admin' && state.clientKey) q.set('c', state.clientKey);
  history.replaceState(null, '', `${location.pathname}${q.size ? `?${q}` : ''}`);
}
function render(html) { setHeader(); view.innerHTML = html; }
function footer() { return '<p class="footer-note">Vision Flow Portal · Private project records · Last refreshed from the secure workspace</p>'; }
function empty(title, body, action = '') { return `<section class="empty"><h1>${esc(title)}</h1><p>${esc(body)}</p>${action}</section>`; }

function normalizeClient(client, slug) {
  const c = client || {};
  c.slug ||= slug; c.feedbackReviews ||= {}; c.signatureReviews ||= {};
  c.projects ||= {};
  Object.entries(c.projects).forEach(([projectSlug, project]) => {
    project.slug ||= projectSlug; project.items ||= []; project.payments ||= []; project.approvals ||= [];
    project.approvals.forEach((approval, index) => { approval.id ||= approvalId(approval, index); });
  });
  return c;
}
function publicSnapshot(client, slug) {
  const projects = JSON.parse(JSON.stringify(client.projects || {}));
  const feedbackReviews = JSON.parse(JSON.stringify(client.feedbackReviews || {}));
  const signatureReviews = JSON.parse(JSON.stringify(client.signatureReviews || {}));
  return { clientSlug: slug, name: client.name || slug, projects, feedbackReviews, signatureReviews, lastUpdated: client.lastUpdated || new Date().toISOString(), portalVersion: 3 };
}
function accessUrl(client) { return `${location.origin}${location.pathname}?access=${client.accessToken}`; }
function clientMetrics(client) {
  const projects = Object.values(client?.projects || {}); let total = 0, done = 0, budget = 0, paid = 0;
  projects.forEach(project => { const p = progress(project); total += p.total; done += p.done; budget += Number(project.budget || 0); paid += (project.payments || []).reduce((sum, payment) => sum + Number(payment.amount || 0), 0); });
  return { projects: projects.length, total, done, budget, paid };
}
function signatureRecords(clientKey, projectKey) { return state.artifacts.signatures[keyFor(clientKey, projectKey)] || []; }
function signatureReview(client, signature) { return client?.signatureReviews?.[signature?.id] || {}; }
function signatureStatus(client, signature) { return signatureReview(client, signature).state || 'pending'; }
function activeSignature(client, clientKey, projectKey) { return [...signatureRecords(clientKey, projectKey)].sort((a, b) => String(b.signedAt || '').localeCompare(String(a.signedAt || ''))).find(signature => signatureStatus(client, signature) !== 'void'); }
function artifactSignature(clientKey, projectKey) { return activeSignature(currentClient(), clientKey, projectKey); }
function artifactConfirm(clientKey, projectKey, approvalKey) { return state.artifacts.confirms[keyFor(clientKey, projectKey, approvalKey)]; }
function storeSignature(clientKey, client, entry) { const projectKey = entry?.projectKey || (client?.projects?.[entry?.id] ? entry.id : null); if (!projectKey) return; const signature = { ...entry, projectKey }; const records = state.artifacts.signatures[keyFor(clientKey, projectKey)] ||= []; const index = records.findIndex(record => record.id === signature.id); if (index >= 0) records[index] = signature; else records.push(signature); }
function storeFeedback(clientKey, entry) { if (!entry?.projectKey) return; const id = keyFor(clientKey, entry.projectKey, Number(entry.itemNumber || 0)); const records = state.feedback[id] ||= []; const index = records.findIndex(record => record.id === entry.id); if (index >= 0) records[index] = entry; else records.push(entry); }
function allProjectFeedback(clientKey, projectKey) { return Object.values(state.feedback).flat().filter(entry => entry.projectKey === projectKey).sort((a, b) => String(b.submittedAt || '').localeCompare(String(a.submittedAt || ''))); }
function findFeedback(id) { return Object.values(state.feedback).flat().find(entry => entry.id === id); }
function storeConfirmation(clientKey, client, id, entry) { for (const [projectKey, project] of Object.entries(client.projects || {})) { const index = (project.approvals || []).findIndex((approval, i) => approvalId(approval, i) === id || `apr_${i}` === id); if (index >= 0) { state.artifacts.confirms[keyFor(clientKey, projectKey, approvalId(project.approvals[index], index))] = entry; return; } } }

async function loadPrivateClients() {
  const snapshot = await getDocs(collection(db, 'portal_clients'));
  state.clients = {};
  snapshot.forEach(record => { const client = normalizeClient(record.data(), record.id); if (!client._deleted) state.clients[record.id] = client; });
  await Promise.all(Object.entries(state.clients).filter(([, client]) => client.accessToken).map(([clientKey, client]) => publishPublicSnapshot(clientKey, client)));
  await hydrateAdminArtifacts();
}
async function hydrateAdminArtifacts() {
  const jobs = [];
  for (const [clientKey, client] of Object.entries(state.clients)) {
    if (!client.accessToken) continue;
    jobs.push(getDocs(collection(db, 'portal_public', client.accessToken, 'sigs')).then(records => records.forEach(record => storeSignature(clientKey, client, { id: record.id, ...record.data() }))).catch(() => {}));
    jobs.push(getDocs(collection(db, 'portal_public', client.accessToken, 'confirms')).then(records => records.forEach(record => {
      const entry = { id: record.id, ...record.data() }; if (entry.kind === 'feedback') storeFeedback(clientKey, entry); else storeConfirmation(clientKey, client, record.id, entry);
    })).catch(() => {}));
  }
  await Promise.all(jobs);
}
async function loadPublic(tokenValue) {
  state.mode = 'client'; state.token = tokenValue; setHeader();
  const record = await getDoc(doc(db, 'portal_public', tokenValue));
  if (!record.exists()) { render(empty('This portal link is not available', 'Ask Vision Flow for a fresh private link.')); return; }
  state.publicClient = normalizeClient(record.data(), record.data().clientSlug || 'client');
  state.clientKey = state.publicClient.clientSlug || 'client';
  const wanted = new URLSearchParams(location.search).get('p');
  state.projectKey = wanted && state.publicClient.projects[wanted] ? wanted : null;
  await hydratePublicArtifacts();
  state.projectKey ? renderProject() : renderClient();
}
async function hydratePublicArtifacts() {
  const client = state.publicClient; const clientKey = state.clientKey; const jobs = [];
  jobs.push(getDocs(collection(db, 'portal_public', state.token, 'sigs')).then(records => records.forEach(record => storeSignature(clientKey, client, { id: record.id, ...record.data() }))).catch(() => {}));
  jobs.push(getDocs(collection(db, 'portal_public', state.token, 'confirms')).then(records => records.forEach(record => {
    const entry = { id: record.id, ...record.data() }; if (entry.kind === 'feedback') storeFeedback(clientKey, entry); else storeConfirmation(clientKey, client, record.id, entry);
  })).catch(() => {}));
  await Promise.all(jobs);
}
async function persistClient(clientKey, client, notice = 'Saved') {
  const c = normalizeClient(client, clientKey); c.lastUpdated = new Date().toISOString(); c.accessToken ||= token();
  await setDoc(doc(db, 'portal_clients', clientKey), c);
  await publishPublicSnapshot(clientKey, c);
  state.clients[clientKey] = c; toast(notice);
}
async function publishPublicSnapshot(clientKey, client) {
  if (!client.accessToken) return;
  await setDoc(doc(db, 'portal_public', client.accessToken), publicSnapshot(client, clientKey));
}

function renderLogin(message = '') {
  state.mode = 'login'; render(`<section class="empty"><p class="eyebrow">Secure workspace</p><h1>Admin sign in</h1><p>Use your Vision Flow administrator account to manage clients and projects.</p><form id="loginForm" class="form-grid" style="text-align:left;margin-top:22px"><div class="field"><label>Email</label><input class="input" type="email" name="email" autocomplete="username" required></div><div class="field"><label>Password</label><input class="input" type="password" name="password" autocomplete="current-password" required></div><button class="button primary" type="submit">Sign in securely</button>${message ? `<p class="small" style="color:var(--rose);margin:0">${esc(message)}</p>` : ''}</form></section>`); }
function renderLegacyLink() { state.mode = 'legacy'; render(`<section class="empty legacy"><p class="eyebrow">Private link updated</p><h1>This link format has been retired</h1><p>Vision Flow now uses an unguessable private access link instead of a client-name URL. Ask the project administrator for a new link.</p></section>`); }
function renderDashboard() {
  state.mode = 'admin'; state.clientKey = null; state.projectKey = null; setUrl();
  const clients = Object.entries(state.clients); const totals = clients.reduce((sum, [, client]) => { const m = clientMetrics(client); sum.clients += 1; sum.projects += m.projects; sum.budget += m.budget; sum.paid += m.paid; return sum; }, { clients: 0, projects: 0, budget: 0, paid: 0 });
  render(`<section class="hero"><p class="eyebrow">Agency workspace</p><h1>Project command center</h1><p class="hero-copy">Open any client to manage projects, payments, delivery logs, approvals, feedback, and private access links.</p></section>
  <section class="stats"><div class="stat"><span>Clients</span><strong>${totals.clients}</strong></div><div class="stat"><span>Projects</span><strong>${totals.projects}</strong></div><div class="stat"><span>Total budget</span><strong>${money(totals.budget)}</strong></div><div class="stat"><span>Collected</span><strong>${money(totals.paid)}</strong></div><div class="stat"><span>Due</span><strong>${money(totals.budget - totals.paid)}</strong></div></section>
  <div class="section-head"><h2>Clients</h2><div class="actions"><button class="button primary" data-action="add-client">Add client</button></div></div>
  <section class="cards">${clients.map(([key, client]) => clientCard(key, client)).join('') || empty('No clients yet', 'Add your first client to start tracking work.')}</section>${footer()}`);
}
function clientCard(clientKey, client) { const m = clientMetrics(client); const percent = m.total ? Math.round(m.done / m.total * 100) : 0; return `<button class="card" data-action="open-client" data-client="${esc(clientKey)}"><div class="card-top"><div><div class="card-name">${esc(client.name || clientKey)}</div><p>${m.projects} project${m.projects === 1 ? '' : 's'} · ${m.done}/${m.total} delivered</p></div><span class="badge ${client.accessToken ? 'active' : ''}">${client.accessToken ? 'Shared' : 'Private'}</span></div><div class="progress"><i style="width:${Math.max(percent, 2)}%"></i></div><p>${percent}% complete</p><div class="numbers"><div><strong>${money(m.budget)}</strong><span>Budget</span></div><div><strong>${money(m.paid)}</strong><span>Paid</span></div><div><strong>${money(m.budget - m.paid)}</strong><span>Due</span></div></div></button>`; }
function renderClient() {
  const client = currentClient(); if (!client) { renderDashboard(); return; } setUrl();
  const admin = state.mode === 'admin'; const projects = Object.entries(client.projects || {}); const m = clientMetrics(client);
  render(`<div class="breadcrumb">${admin ? '<button data-action="dashboard">Dashboard</button><span>/</span>' : ''}<span>${esc(client.name || state.clientKey)}</span></div><section class="hero"><p class="eyebrow">${admin ? 'Client workspace' : 'Your private workspace'}</p><h1>${esc(client.name || state.clientKey)}</h1><p class="hero-copy">${admin ? `${esc(client.email || '')}${client.phone ? ` · ${esc(client.phone)}` : ''}` : 'Review every project, delivery update, payment record, and approval in one place.'}</p>${admin ? `<div class="section-head" style="margin:20px 0 0"><div class="actions"><button class="button" data-action="copy-link">Copy private link</button><button class="button" data-action="preview-client">Preview client view</button><button class="button" data-action="edit-client">Edit client</button></div></div>` : ''}</section><section class="stats"><div class="stat"><span>Projects</span><strong>${m.projects}</strong></div><div class="stat"><span>Delivered</span><strong>${m.done}/${m.total}</strong></div><div class="stat"><span>Budget</span><strong>${money(m.budget)}</strong></div><div class="stat"><span>Paid</span><strong>${money(m.paid)}</strong></div><div class="stat"><span>Due</span><strong>${money(m.budget - m.paid)}</strong></div></section><div class="section-head"><h2>Projects</h2>${admin ? '<div class="actions"><button class="button primary" data-action="add-project">Add project</button></div>' : ''}</div><section class="cards">${projects.map(([key, project]) => projectCard(key, project)).join('') || empty('No projects yet', 'Projects will appear here as soon as they are created.')}</section>${footer()}`);
}
function projectCard(projectKey, project) { const p = progress(project); return `<button class="card" data-action="open-project" data-project="${esc(projectKey)}"><div class="card-top"><div><div class="card-name">${esc(project.name || projectKey)}</div><p>${p.total} items · ${money(project.rate || 0)} per item</p></div><span class="badge ${esc(project.status || 'active')}">${esc(LABEL[project.status] || project.status || 'Active')}</span></div><div class="progress"><i style="width:${Math.max(p.percent, 2)}%"></i></div><p>${p.done} of ${p.total} complete · ${p.percent}%</p><div class="numbers"><div><strong>${p.done}</strong><span>Done</span></div><div><strong>${p.total - p.done}</strong><span>Remaining</span></div><div><strong>${money(project.budget || 0)}</strong><span>Budget</span></div></div></button>`; }
function renderProject() {
  const client = currentClient(); const project = currentProject(); if (!client || !project) { renderClient(); return; } setUrl();
  const admin = state.mode === 'admin'; const p = progress(project); const payments = project.payments || []; const paid = payments.reduce((sum, payment) => sum + Number(payment.amount || 0), 0); const due = Number(project.budget || 0) - paid; const feedbackCount = allProjectFeedback(state.clientKey, state.projectKey).length;
  const breadcrumb = `<div class="breadcrumb">${admin ? '<button data-action="dashboard">Dashboard</button><span>/</span>' : ''}<button data-action="open-client">${esc(client.name || state.clientKey)}</button><span>/</span><span>${esc(project.name || state.projectKey)}</span></div>`;
  const actions = admin ? `<div class="actions"><button class="button" data-action="edit-project">Edit project</button><button class="button" data-action="add-payment">Record payment</button><button class="button" data-action="add-approval">Request approval</button><button class="button danger" data-action="delete-project">Delete project</button></div>` : '';
  const overview = `<section class="metrics"><div class="metric"><span>Complete</span><strong>${p.percent}%</strong></div><div class="metric"><span>Delivered</span><strong>${p.done}/${p.total}</strong></div><div class="metric"><span>Paid</span><strong>${money(paid)}</strong></div><div class="metric"><span>Due</span><strong>${money(due)}</strong></div></section><div class="progress"><i style="width:${Math.max(p.percent, 2)}%"></i></div><div class="two-col"><section class="panel">${paymentPanel(payments, paid, admin)}</section><section class="panel">${approvalPanel(client, project, admin)}</section></div>${agreementPanel(client, project, admin)}${feedbackPanel(client, project, admin)}`;
  const log = productionLog(project, admin);
  render(`${breadcrumb}<section class="hero"><p class="eyebrow">${admin ? 'Project management' : 'Project overview'}</p><h1>${esc(project.name || state.projectKey)}</h1><p class="hero-copy">${p.total} deliverables · ${money(project.rate || 0)} each · <span class="badge ${esc(project.status || 'active')}">${esc(LABEL[project.status] || project.status || 'Active')}</span>${project.lastUpdated || client.lastUpdated ? ` · Updated ${esc(new Date(project.lastUpdated || client.lastUpdated).toLocaleDateString())}` : ''}</p><div class="section-head" style="margin:20px 0 0"><div class="actions"><button class="button" data-action="print-report">Print / save report</button>${!admin ? '<button class="button primary" data-action="leave-project-feedback">Project feedback / revision</button>' : ''}${actions}</div></div></section><div class="tabbar"><button class="${state.tab === 'overview' ? 'active' : ''}" data-action="tab-overview">Overview</button><button class="${state.tab === 'log' ? 'active' : ''}" data-action="tab-log">Production log · ${p.total}</button>${feedbackCount ? `<span class="badge revision" style="align-self:center">${feedbackCount} client request${feedbackCount === 1 ? '' : 's'}</span>` : ''}</div>${state.tab === 'overview' ? overview : log}${footer()}`);
}
function paymentPanel(payments, paid, admin) { if (!payments.length) return '<div class="panel-head"><h3>Payments</h3></div><p class="muted small">No payment has been recorded.</p>'; return `<div class="panel-head"><h3>Payments</h3><span class="badge active">${money(paid)} paid</span></div><div class="list">${payments.map((payment, index) => { const proof = safeHttpUrl(payment.proofUrl); return `<div class="list-row"><div class="record"><span class="record-mark ok">৳</span><div><strong>${money(payment.amount)} · ${esc(payment.type || 'Payment')}</strong><p>${esc(payment.date || 'Date not set')}${payment.note ? ` · ${esc(payment.note)}` : ''}</p>${proof ? `<a href="${esc(proof)}" target="_blank" rel="noopener"><img class="payment-proof" src="${esc(proof)}" alt="Payment proof"></a>` : ''}</div>${admin ? `<div class="row-actions"><button class="icon-button" data-action="edit-payment" data-index="${index}" title="Edit payment">✎</button><button class="icon-button" data-action="delete-payment" data-index="${index}" title="Delete payment">×</button></div>` : ''}</div></div>`; }).join('')}</div>`; }
function approvalPanel(client, project, admin) { const approvals = project.approvals || []; if (!approvals.length) return '<div class="panel-head"><h3>Approvals</h3></div><p class="muted small">No approval is waiting right now.</p>'; return `<div class="panel-head"><h3>Approvals</h3><span class="badge">${approvals.length} update${approvals.length === 1 ? '' : 's'}</span></div><div class="list">${approvals.map((approval, index) => { const id = approvalId(approval, index); const confirmed = artifactConfirm(state.clientKey, state.projectKey, id); return `<div class="list-row"><div class="record"><span class="record-mark ${confirmed ? 'ok' : ''}">${confirmed ? '✓' : '!'}</span><div><strong>${esc(approval.title || `Update ${index + 1}`)}</strong><p>${esc(approval.desc || 'Project update is ready for review.')} · ${confirmed ? `Confirmed ${esc(new Date(confirmed.confirmedAt).toLocaleDateString())}` : 'Awaiting confirmation'}</p>${!admin && !confirmed ? `<button class="button small" style="margin-top:8px" data-action="confirm-approval" data-approval="${esc(id)}">Confirm update</button>` : ''}</div>${admin ? `<div class="row-actions"><button class="icon-button" data-action="delete-approval" data-index="${index}" title="Remove approval request">×</button></div>` : ''}</div></div>`; }).join('')}</div>`; }
function agreementPanel(client, project, admin) { const records = [...signatureRecords(state.clientKey, state.projectKey)].sort((a, b) => String(b.signedAt || '').localeCompare(String(a.signedAt || ''))); const signature = activeSignature(client, state.clientKey, state.projectKey); if (admin) { if (!records.length) return '<section class="agreement"><h3>Agreement record</h3><p>No client signature has been submitted yet.</p></section>'; return `<section class="agreement"><div class="panel-head"><h3>Agreement records</h3><span class="badge">${records.length} record${records.length === 1 ? '' : 's'}</span></div><div class="list">${records.map(record => { const review = signatureReview(client, record); const status = signatureStatus(client, record); const image = safeSignatureImage(record.image); const statusText = status === 'verified' ? 'Verified' : status === 'void' ? 'Voided / replaced' : 'Awaiting verification'; return `<div class="list-row"><div class="record"><span class="record-mark ${status === 'verified' ? 'ok' : ''}">${status === 'verified' ? '✓' : status === 'void' ? '—' : '!'}</span><div><strong>${esc(record.name || 'Client signature')}</strong><p>${esc(statusText)} · Signed ${esc(new Date(record.signedAt).toLocaleString())}${review.message ? ` · ${esc(review.message)}` : ''}</p>${image ? `<img src="${esc(image)}" alt="Client signature" style="max-width:230px;max-height:70px;display:block;margin-top:10px">` : ''}</div><div class="row-actions">${status === 'pending' ? `<button class="button small" data-action="verify-signature" data-signature="${esc(record.id)}">Verify</button>` : ''}${status !== 'void' ? `<button class="button small danger" data-action="void-signature" data-signature="${esc(record.id)}">Void / replace</button>` : ''}</div></div></div>`; }).join('')}</div><p class="small muted">Voiding preserves the signed record in the audit trail and lets the client submit a replacement; it does not silently destroy evidence.</p></section>`; } if (signature) { const review = signatureReview(client, signature); const image = safeSignatureImage(signature.image); const status = signatureStatus(client, signature); return `<section class="agreement"><h3>Agreement record</h3><p>Signed by ${esc(signature.name || 'Client')} on ${esc(new Date(signature.signedAt).toLocaleString())}. ${status === 'verified' ? 'Verified by Vision Flow.' : 'Awaiting Vision Flow verification.'}</p>${image ? `<img src="${esc(image)}" alt="Client signature" style="max-width:230px;max-height:90px;display:block;margin-top:10px">` : ''}${review.message ? `<p class="small">Vision Flow note: ${esc(review.message)}</p>` : ''}<p class="small">This is a project record. Confirm its legal standing for your local jurisdiction where needed.</p></section>`; } const previous = records.length ? '<p class="small">A previous signature was voided. Please submit a fresh signature only after reviewing the revised terms.</p>' : ''; return `<section class="agreement"><h3>Project agreement</h3><p>Before signing, confirm the scope (${projectTotal(project)} deliverables), agreed budget (${money(project.budget || 0)}), delivery milestones, and payment terms with Vision Flow.</p><button class="button primary" data-action="sign-agreement">Review and sign</button>${previous}<p class="small">A signed record is time-stamped and cannot be edited from this portal.</p></section>`; }
function feedbackPanel(client, project, admin) { const entries = allProjectFeedback(state.clientKey, state.projectKey); if (!entries.length) return `<section class="panel" style="margin-top:18px"><div class="panel-head"><h3>${admin ? 'Client feedback & revisions' : 'Your feedback & revisions'}</h3></div><p class="muted small">${admin ? 'No client feedback has been received for this project.' : 'No request submitted yet. Use the project button or any video row to send feedback or a revision request.'}</p></section>`; return `<section class="panel" style="margin-top:18px"><div class="panel-head"><h3>${admin ? 'Client feedback & revisions' : 'Your feedback & revisions'}</h3><span class="badge revision">${entries.length}</span></div><div class="list">${entries.map(entry => { const review = client.feedbackReviews?.[entry.id] || {}; const status = review.status || 'new'; const target = entry.itemNumber ? `Item ${String(entry.itemNumber).padStart(3, '0')}` : 'Project-wide'; const label = entry.requestType === 'revision' ? 'Revision request' : entry.requestType === 'question' ? 'Question' : 'Feedback'; return `<div class="list-row"><div class="record"><span class="record-mark ${status === 'resolved' ? 'ok' : ''}">${status === 'resolved' ? '✓' : '✦'}</span><div><strong>${esc(label)} · ${esc(target)}</strong><p>${esc(entry.message || '')}</p><p class="small muted">Sent ${esc(new Date(entry.submittedAt).toLocaleString())} · ${esc(status.replace('-', ' '))}${review.response ? ` · Vision Flow: ${esc(review.response)}` : ''}</p></div>${admin ? `<div class="row-actions"><button class="button small" data-action="review-feedback" data-feedback="${esc(entry.id)}">Review / respond</button></div>` : ''}</div></div>`; }).join('')}</div></section>`; }
function productionLog(project, admin) { const rows = projectItems(project).map((item, index) => { const itemNumber = Number(item.n || index + 1); const feedback = state.feedback[keyFor(state.clientKey, state.projectKey, itemNumber)] || []; const delivery = safeHttpUrl(item.dl); return `<tr data-item-row data-status="${esc(itemStatus(item))}" data-search="${esc(`${item.n} ${item.b || ''} ${item.t || ''} ${item.no || ''}`.toLowerCase())}"><td>${String(itemNumber).padStart(3, '0')}</td><td><strong>${esc(item.b || '—')}</strong></td><td>${esc(item.t || '—')}</td><td><span class="badge ${itemStatus(item)}">${esc(LABEL[itemStatus(item)])}</span></td><td>${esc(item.sd || '—')}</td><td>${esc(item.dd || '—')}</td><td>${esc(item.dur || '—')}</td><td>${delivery ? `<a href="${esc(delivery)}" target="_blank" rel="noopener">Open</a>` : '—'}</td><td>${esc(item.no || '—')}${feedback.length ? `<span class="feedback-note">${feedback.length} client request${feedback.length === 1 ? '' : 's'}</span>` : ''}</td><td><div class="row-actions">${admin ? `<button class="icon-button" data-action="edit-item" data-index="${index}" title="Edit item">✎</button>` : `<button class="button small" data-action="leave-feedback" data-item="${itemNumber}">Feedback / revision</button>`}</div></td></tr>`; }).join(''); return `<section class="panel" style="margin-top:18px"><div class="filter-row"><input class="input" id="itemSearch" data-role="item-search" placeholder="Search delivery log"><select class="select" id="itemStatus" data-role="item-status"><option value="">All statuses</option>${STATUS.map(status => `<option value="${status}">${LABEL[status]}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>#</th><th>Breed / item</th><th>Title</th><th>Status</th><th>Started</th><th>Delivered</th><th>Duration</th><th>Link</th><th>Notes</th><th></th></tr></thead><tbody>${rows || '<tr><td colspan="10" class="muted">No production items have been added.</td></tr>'}</tbody></table></div></section>`; }

function openModal(title, subtitle, body, onSubmit, submitLabel = 'Save') { modalLayer.hidden = false; modalContent.innerHTML = `<h2 id="modalTitle">${esc(title)}</h2>${subtitle ? `<p class="modal-sub">${esc(subtitle)}</p>` : ''}<form id="modalForm">${body}<div class="form-actions"><button class="button" type="button" data-action="close-modal">Cancel</button><button class="button primary" type="submit">${esc(submitLabel)}</button></div></form>`; const form = $('modalForm'); form.addEventListener('submit', event => { event.preventDefault(); safely(async () => { const submit = form.querySelector('[type="submit"]'); submit.disabled = true; submit.textContent = 'Saving…'; await onSubmit(new FormData(form), form); }); }); }
function closeModal() { modalLayer.hidden = true; modalContent.innerHTML = ''; }
function field(label, name, value = '', type = 'text', extra = '') { return `<div class="field"><label>${esc(label)}</label><input class="input" name="${esc(name)}" type="${esc(type)}" value="${esc(value)}" ${extra}></div>`; }
function textarea(label, name, value = '', extra = '') { return `<div class="field"><label>${esc(label)}</label><textarea class="textarea" name="${esc(name)}" ${extra}>${esc(value)}</textarea></div>`; }
function select(label, name, options, value = '') { return `<div class="field"><label>${esc(label)}</label><select class="select" name="${esc(name)}" style="width:100%">${options.map(option => `<option value="${esc(option.value)}" ${option.value === value ? 'selected' : ''}>${esc(option.label)}</option>`).join('')}</select></div>`; }
function requireAdmin() { if (state.mode !== 'admin') throw new Error('Admin access required.'); }
function openClientForm(edit = false) { const client = edit ? currentClient() : {}; const body = `<div class="form-grid">${field('Client name', 'name', client?.name || '', 'text', 'required')}${!edit ? field('URL label', 'slug', '', 'text', 'required pattern="[a-z0-9-]+"') : ''}${field('Email', 'email', client?.email || '', 'email')}${field('Phone', 'phone', client?.phone || '')}</div>`; openModal(edit ? 'Edit client' : 'Add client', 'Client records stay private; the shared link uses a separate secret access token.', body, async data => { requireAdmin(); const key = edit ? state.clientKey : text(data.get('slug')).toLowerCase(); if (!/^[a-z0-9-]+$/.test(key)) throw new Error('Use lowercase letters, numbers, and hyphens for the URL label.'); if (!edit && state.clients[key]) throw new Error('This URL label is already in use.'); const next = edit ? currentClient() : { slug: key, projects: {}, createdAt: new Date().toISOString() }; next.name = text(data.get('name')); next.email = text(data.get('email')); next.phone = text(data.get('phone')); await persistClient(key, next, edit ? 'Client updated' : 'Client created'); state.clientKey = key; state.projectKey = null; closeModal(); renderClient(); }); }
function openProjectForm(edit = false) { const project = edit ? currentProject() : {}; const body = `<div class="form-grid two">${field('Project name', 'name', project?.name || '', 'text', 'required')}${!edit ? field('URL label', 'slug', '', 'text', 'required pattern="[a-z0-9-]+"') : ''}${field('Total deliverables', 'total', project?.totalItems || 100, 'number', `min="${edit ? projectItems(project).length : 1}" required`)}${field('Rate (BDT)', 'rate', project?.rate || 400, 'number', 'min="0" required')}${field('Budget (BDT)', 'budget', project?.budget || 40000, 'number', 'min="0" required')}${select('Project status', 'status', ['active', 'paused', 'completed'].map(value => ({ value, label: LABEL[value] || value })), project?.status || 'active')}</div>`; openModal(edit ? 'Edit project' : 'Add project', 'The production log is generated automatically for the selected number of deliverables.', body, async data => { requireAdmin(); const client = currentClient(); const key = edit ? state.projectKey : text(data.get('slug')).toLowerCase(); if (!/^[a-z0-9-]+$/.test(key)) throw new Error('Use lowercase letters, numbers, and hyphens for the URL label.'); if (!edit && client.projects[key]) throw new Error('This project URL label is already in use.'); const total = Number(data.get('total')); if (!Number.isInteger(total) || total < 1) throw new Error('Enter a whole number of deliverables.'); const next = edit ? currentProject() : { slug: key, items: [], payments: [], approvals: [], createdAt: new Date().toISOString() }; if (total < projectItems(next).length) throw new Error(`This project already has ${projectItems(next).length} production rows. Removing rows is intentionally blocked to protect existing records.`); next.name = text(data.get('name')); next.totalItems = total; next.rate = Number(data.get('rate')); next.budget = Number(data.get('budget')); next.status = text(data.get('status')); for (let n = projectItems(next).length + 1; n <= total; n += 1) next.items.push({ n, b: '', t: '', s: 'pending', sd: '', dd: '', dur: '', dl: '', no: '' }); client.projects[key] = next; await persistClient(state.clientKey, client, edit ? 'Project updated' : 'Project created'); state.projectKey = key; state.tab = 'overview'; closeModal(); renderProject(); }); }
function openItemForm(index) { const project = currentProject(); const item = projectItems(project)[index]; if (!item) return; const statuses = STATUS.map(value => ({ value, label: LABEL[value] })); const clientNotes = state.feedback[keyFor(state.clientKey, state.projectKey, item.n)] || []; const feedbackPanel = clientNotes.length ? `<div class="agreement"><h3>Client feedback</h3>${clientNotes.map(note => `<p><strong>${esc(new Date(note.submittedAt).toLocaleString())}</strong><br>${esc(note.message)}</p>`).join('')}</div>` : ''; const body = `<div class="form-grid two">${field('Breed / item', 'breed', item.b || '')}${field('Title', 'title', item.t || '')}${select('Status', 'status', statuses, itemStatus(item))}${field('Started', 'started', item.sd || '')}${field('Delivered', 'delivered', item.dd || '')}${field('Duration', 'duration', item.dur || '')}</div>${field('Delivery link', 'link', item.dl || '', 'url')}${textarea('Internal note', 'note', item.no || '')}${feedbackPanel}`; openModal(`Edit item ${item.n || index + 1}`, 'Only explicit editing changes an item; row clicks never open the editor.', body, async data => { requireAdmin(); const before = itemStatus(item); item.b = text(data.get('breed')); item.t = text(data.get('title')); item.s = text(data.get('status')); item.sd = text(data.get('started')) || (item.s === 'progress' && !item.sd ? dateNow() : item.sd); item.dd = text(data.get('delivered')) || (item.s === 'delivered' && !item.dd ? dateNow() : item.dd); item.dur = text(data.get('duration')); item.dl = text(data.get('link')); item.no = text(data.get('note')); if (before !== item.s && isDone(item) && confirm('Create a client approval request for this completed item?')) { project.approvals.push({ id: `approval-${Date.now()}-${index}`, title: `${item.b || `Item ${item.n || index + 1}`} — ${LABEL[item.s]}`, desc: item.t || 'Delivery is ready for review.', createdAt: new Date().toISOString() }); } await persistClient(state.clientKey, currentClient(), 'Item updated'); closeModal(); renderProject(); }); }
function openPaymentForm(index = null) { const project = currentProject(); const existing = index === null ? null : project.payments[index]; const body = `<div class="form-grid two">${field('Date', 'date', existing?.date || dateNow(), 'text', 'required')}${field('Amount (BDT)', 'amount', existing?.amount || '', 'number', 'min="0" required')}${select('Payment type', 'type', ['Advance', 'Milestone', 'bKash', 'Nagad', 'Bank transfer', 'Final'].map(value => ({ value, label: value })), existing?.type || 'Advance')}${field('Payment proof image', 'proof', '', 'file', 'accept="image/*"')}</div>${textarea('Note', 'note', existing?.note || '')}<img id="proofPreview" class="preview ${existing?.proofUrl ? 'visible' : ''}" ${existing?.proofUrl ? `src="${esc(existing.proofUrl)}"` : ''} alt="Payment proof preview">`; openModal(existing ? 'Edit payment' : 'Record payment', 'A preview appears immediately; the image uploads only when you save.', body, async (data, form) => { requireAdmin(); const payment = existing || {}; payment.date = text(data.get('date')); payment.amount = Number(data.get('amount')); payment.type = text(data.get('type')); payment.note = text(data.get('note')); const file = form.elements.proof?.files?.[0]; if (file) payment.proofUrl = await uploadProof(file, form.querySelector('[type="submit"]')); if (!existing) { payment.recordedAt = new Date().toISOString(); project.payments.push(payment); } await persistClient(state.clientKey, currentClient(), existing ? 'Payment updated' : 'Payment recorded'); closeModal(); renderProject(); }); }
function openApprovalForm() { const body = `<div class="form-grid">${field('Approval title', 'title', '', 'text', 'required')}${textarea('What should the client review?', 'desc', '', 'required')}</div>`; openModal('Request client approval', 'The client can confirm once; the time-stamped confirmation is retained as a project record.', body, async data => { requireAdmin(); currentProject().approvals.push({ id: `approval-${Date.now()}-${token().slice(0, 6)}`, title: text(data.get('title')), desc: text(data.get('desc')), createdAt: new Date().toISOString() }); await persistClient(state.clientKey, currentClient(), 'Approval request created'); closeModal(); renderProject(); }); }
async function uploadProof(file, submit) { submit.textContent = 'Uploading proof…'; const payload = new FormData(); payload.append('file', file); payload.append('upload_preset', CLOUDINARY.preset); const response = await fetch(`https://api.cloudinary.com/v1_1/${CLOUDINARY.cloud}/image/upload`, { method: 'POST', body: payload }); if (!response.ok) throw new Error('Payment proof upload failed.'); const result = await response.json(); if (!result.secure_url) throw new Error('Payment proof upload failed.'); return result.secure_url; }

let signaturePad;
function openSignatureForm() { const project = currentProject(); const body = `<div class="form-grid">${field('Your full name', 'name', '', 'text', 'required')}<div class="field"><label>Draw your signature</label><canvas id="signatureCanvas" class="signature-pad"></canvas><button class="button ghost" type="button" data-action="clear-signature">Clear signature</button></div><p class="small muted">Signing creates a time-stamped project record. Review the commercial agreement separately where formal legal advice is needed.</p></div>`; openModal('Sign project agreement', `Project: ${project.name || state.projectKey}`, body, async data => { if (!signaturePad?.drawn) throw new Error('Draw your signature before submitting.'); const id = `signature-${state.projectKey}-${Date.now()}-${token().slice(0, 8)}`; const record = { id, projectKey: state.projectKey, name: text(data.get('name')), image: signaturePad.canvas.toDataURL('image/png'), signedAt: new Date().toISOString(), userAgent: navigator.userAgent }; await setDoc(doc(db, 'portal_public', state.token, 'sigs', id), record); storeSignature(state.clientKey, currentClient(), record); closeModal(); toast('Agreement record submitted for verification'); renderProject(); }, 'Submit signature'); setTimeout(initSignaturePad, 0); }
function initSignaturePad() { const canvas = $('signatureCanvas'); if (!canvas) return; const bounds = canvas.getBoundingClientRect(); const pixelRatio = window.devicePixelRatio || 1; canvas.width = bounds.width * pixelRatio; canvas.height = bounds.height * pixelRatio; const ctx = canvas.getContext('2d'); ctx.scale(pixelRatio, pixelRatio); ctx.strokeStyle = '#38bdf8'; ctx.lineWidth = 2.4; ctx.lineCap = 'round'; let drawing = false; signaturePad = { canvas, ctx, drawn: false }; const point = event => { const r = canvas.getBoundingClientRect(); return { x: event.clientX - r.left, y: event.clientY - r.top }; }; canvas.addEventListener('pointerdown', event => { drawing = true; canvas.setPointerCapture(event.pointerId); const p = point(event); ctx.beginPath(); ctx.moveTo(p.x, p.y); event.preventDefault(); }); canvas.addEventListener('pointermove', event => { if (!drawing) return; const p = point(event); ctx.lineTo(p.x, p.y); ctx.stroke(); signaturePad.drawn = true; event.preventDefault(); }); ['pointerup', 'pointercancel', 'pointerleave'].forEach(name => canvas.addEventListener(name, () => drawing = false)); }
function clearSignature() { if (!signaturePad) return; const { canvas, ctx } = signaturePad; ctx.clearRect(0, 0, canvas.width, canvas.height); signaturePad.drawn = false; }
function openFeedbackForm(itemNumber = 0) { const target = itemNumber ? `item ${itemNumber}` : 'this project'; const body = `<div class="form-grid">${select('Request type', 'requestType', [{ value: 'feedback', label: 'Feedback' }, { value: 'revision', label: 'Revision request' }, { value: 'question', label: 'Question' }], 'feedback')}${textarea('Message', 'message', '', 'required placeholder="Explain the feedback, question, or change you need…"')}<p class="small muted">Your message is saved as a time-stamped project record for the Vision Flow administrator. You will see its resolution status and reply here.</p></div>`; openModal(`Feedback for ${target}`, 'Use this for a delivery note, question, or revision request.', body, async data => { const entry = { kind: 'feedback', requestType: text(data.get('requestType')) || 'feedback', projectKey: state.projectKey, itemNumber: Number(itemNumber || 0), message: text(data.get('message')), submittedAt: new Date().toISOString(), userAgent: navigator.userAgent }; const id = `feedback-${Date.now()}-${token().slice(0, 8)}`; await setDoc(doc(db, 'portal_public', state.token, 'confirms', id), entry); storeFeedback(state.clientKey, { id, ...entry }); closeModal(); toast('Your request was sent to Vision Flow'); renderProject(); }, 'Send request'); }
function openFeedbackReview(feedbackId) { requireAdmin(); const entry = findFeedback(feedbackId); if (!entry) throw new Error('This client request could not be found.'); const client = currentClient(); const review = client.feedbackReviews?.[feedbackId] || {}; const target = entry.itemNumber ? `Item ${String(entry.itemNumber).padStart(3, '0')}` : 'Project-wide request'; const body = `<div class="agreement"><h3>${esc(entry.requestType === 'revision' ? 'Revision request' : entry.requestType || 'Feedback')} · ${esc(target)}</h3><p>${esc(entry.message || '')}</p><p class="small muted">Submitted ${esc(new Date(entry.submittedAt).toLocaleString())}</p></div><div class="form-grid">${select('Status', 'status', [{ value: 'new', label: 'New' }, { value: 'in-progress', label: 'In progress' }, { value: 'resolved', label: 'Resolved' }, { value: 'closed', label: 'Closed' }], review.status || 'new')}${textarea('Reply visible to client', 'response', review.response || '', 'placeholder="Tell the client what happens next…"')}</div>`; openModal('Review client request', 'Update the status and send a client-visible response.', body, async data => { const next = currentClient(); next.feedbackReviews ||= {}; next.feedbackReviews[feedbackId] = { status: text(data.get('status')) || 'new', response: text(data.get('response')), updatedAt: new Date().toISOString() }; await persistClient(state.clientKey, next, 'Client request updated'); closeModal(); renderProject(); }, 'Save response'); }
function openSignatureReview(signatureId, desiredState) { requireAdmin(); const signature = signatureRecords(state.clientKey, state.projectKey).find(record => record.id === signatureId); if (!signature) throw new Error('This signature record could not be found.'); const isVoid = desiredState === 'void'; const body = `<div class="agreement"><h3>${esc(signature.name || 'Client signature')}</h3><p>Signed ${esc(new Date(signature.signedAt).toLocaleString())}. ${isVoid ? 'Voiding preserves the original signed record and reopens signing for the client.' : 'Verification marks the submitted record as reviewed by Vision Flow.'}</p></div>${textarea('Client-visible note', 'message', '', `placeholder="${isVoid ? 'Why a replacement is needed…' : 'Optional verification note…'}"`)}`; openModal(isVoid ? 'Void / replace signature' : 'Verify signature', isVoid ? 'The original record remains in the audit trail.' : 'Confirm that Vision Flow reviewed this signature.', body, async data => { const client = currentClient(); client.signatureReviews ||= {}; client.signatureReviews[signatureId] = { state: isVoid ? 'void' : 'verified', message: text(data.get('message')), updatedAt: new Date().toISOString() }; await persistClient(state.clientKey, client, isVoid ? 'Signature voided; client can submit a replacement' : 'Signature verified'); closeModal(); renderProject(); }, isVoid ? 'Void active signature' : 'Verify signature'); }
async function confirmApproval(id) { const existing = artifactConfirm(state.clientKey, state.projectKey, id); if (existing) { toast('This update has already been confirmed.'); return; } if (!confirm('Confirm this project update? This confirmation cannot be changed in the portal.')) return; const record = { confirmedAt: new Date().toISOString(), userAgent: navigator.userAgent }; await setDoc(doc(db, 'portal_public', state.token, 'confirms', id), record); state.artifacts.confirms[keyFor(state.clientKey, state.projectKey, id)] = record; toast('Update confirmed'); renderProject(); }
function printReport() { const client = currentClient(); const project = currentProject(); if (!client || !project) return; const p = progress(project); const paid = (project.payments || []).reduce((sum, payment) => sum + Number(payment.amount || 0), 0); const signed = artifactSignature(state.clientKey, state.projectKey); const signatureImage = safeSignatureImage(signed?.image); const win = window.open('', '_blank'); if (!win) { toast('Allow pop-ups to create a report.', 'error'); return; } const safe = value => esc(value); win.document.write(`<!doctype html><html><head><title>${safe(project.name)} — Vision Flow report</title><style>body{font-family:Arial,sans-serif;color:#152238;max-width:800px;margin:34px auto;padding:0 20px}header{display:flex;justify-content:space-between;border-bottom:3px solid #0891b2;padding-bottom:16px}h1{margin:0;font-size:27px;color:#0f5e74}h2{font-size:17px;margin-top:28px;border-bottom:1px solid #dbe4ef;padding-bottom:7px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.stat{padding:12px;border:1px solid #dbe4ef;border-radius:8px}.stat small{color:#64748b}.stat strong{display:block;font-size:20px;margin-top:5px}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:9px;border-bottom:1px solid #dbe4ef;text-align:left}th{background:#f2f7fb;color:#476078}@media print{body{margin:0;max-width:none}}</style></head><body><header><div><img src="${location.origin}/logo.png" style="height:50px;max-width:170px;object-fit:contain"><h1>Vision Flow</h1><small>Project record</small></div><div style="text-align:right"><small>Generated ${safe(new Date().toLocaleString())}</small><br><small>visionflow-bd.github.io</small></div></header><h2>${safe(project.name)}</h2><p><strong>Client:</strong> ${safe(client.name || state.clientKey)} &nbsp; · &nbsp; <strong>Status:</strong> ${safe(project.status || 'active')}</p><section class="grid"><div class="stat"><small>Complete</small><strong>${p.percent}%</strong></div><div class="stat"><small>Delivered</small><strong>${p.done}/${p.total}</strong></div><div class="stat"><small>Budget</small><strong>${money(project.budget)}</strong></div><div class="stat"><small>Paid</small><strong>${money(paid)}</strong></div></section><h2>Payment record</h2><table><thead><tr><th>Date</th><th>Amount</th><th>Type</th><th>Note</th></tr></thead><tbody>${(project.payments || []).map(payment => `<tr><td>${safe(payment.date)}</td><td>${money(payment.amount)}</td><td>${safe(payment.type)}</td><td>${safe(payment.note)}</td></tr>`).join('') || '<tr><td colspan="4">No payment recorded</td></tr>'}</tbody></table><h2>Approvals</h2><table><thead><tr><th>Update</th><th>Status</th></tr></thead><tbody>${(project.approvals || []).map((approval, index) => { const confirmed = artifactConfirm(state.clientKey, state.projectKey, approvalId(approval, index)); return `<tr><td><strong>${safe(approval.title)}</strong><br><small>${safe(approval.desc)}</small></td><td>${confirmed ? `Confirmed ${safe(new Date(confirmed.confirmedAt).toLocaleString())}` : 'Awaiting confirmation'}</td></tr>`; }).join('') || '<tr><td colspan="2">No approvals recorded</td></tr>'}</tbody></table>${signed ? `<h2>Agreement signature</h2><p>Signed by ${safe(signed.name)} on ${safe(new Date(signed.signedAt).toLocaleString())}</p>${signatureImage ? `<img src="${safe(signatureImage)}" style="max-width:220px;max-height:80px">` : ''}` : ''}<p style="margin-top:35px;color:#64748b;font-size:10px">This document is a generated project record. Obtain local legal advice if a specific legal form is required.</p></body></html>`); win.document.close(); win.focus(); setTimeout(() => win.print(), 250); }

function applyFilters() { const q = text($('itemSearch')?.value).toLowerCase(); const status = text($('itemStatus')?.value); document.querySelectorAll('[data-item-row]').forEach(row => { row.hidden = Boolean((q && !row.dataset.search.includes(q)) || (status && row.dataset.status !== status)); }); }
async function copyClientLink() { const client = currentClient(); if (!client?.accessToken) { await persistClient(state.clientKey, client, 'Private link created'); } const url = accessUrl(currentClient()); try { await navigator.clipboard.writeText(url); toast('Private link copied'); } catch { prompt('Copy this private link:', url); } }

async function handleAction(action, source) {
  if (action === 'close-modal') return closeModal();
  if (action === 'dashboard') return renderDashboard();
  if (action === 'logout') return signOut(auth);
  if (action === 'add-client') return openClientForm(false);
  if (action === 'edit-client') return openClientForm(true);
  if (action === 'open-client') { state.clientKey = source.dataset.client || state.clientKey; state.projectKey = null; state.tab = 'overview'; return renderClient(); }
  if (action === 'copy-link') return copyClientLink();
  if (action === 'preview-client') { const client = currentClient(); if (!client?.accessToken) await persistClient(state.clientKey, client, 'Private link created'); window.open(accessUrl(currentClient()), '_blank'); return; }
  if (action === 'add-project') return openProjectForm(false);
  if (action === 'edit-project') return openProjectForm(true);
  if (action === 'open-project') { state.projectKey = source.dataset.project; state.tab = 'overview'; return renderProject(); }
  if (action === 'delete-project') { requireAdmin(); if (confirm(`Delete “${currentProject().name || state.projectKey}”? This cannot be undone.`)) { delete currentClient().projects[state.projectKey]; await persistClient(state.clientKey, currentClient(), 'Project deleted'); state.projectKey = null; renderClient(); } return; }
  if (action === 'tab-overview') { state.tab = 'overview'; return renderProject(); }
  if (action === 'tab-log') { state.tab = 'log'; return renderProject(); }
  if (action === 'edit-item') return openItemForm(Number(source.dataset.index));
  if (action === 'add-payment') return openPaymentForm();
  if (action === 'edit-payment') return openPaymentForm(Number(source.dataset.index));
  if (action === 'delete-payment') { requireAdmin(); if (confirm('Delete this payment record?')) { currentProject().payments.splice(Number(source.dataset.index), 1); await persistClient(state.clientKey, currentClient(), 'Payment deleted'); renderProject(); } return; }
  if (action === 'add-approval') return openApprovalForm();
  if (action === 'delete-approval') { requireAdmin(); if (confirm('Delete this approval request?')) { currentProject().approvals.splice(Number(source.dataset.index), 1); await persistClient(state.clientKey, currentClient(), 'Approval deleted'); renderProject(); } return; }
  if (action === 'confirm-approval') return confirmApproval(source.dataset.approval);
  if (action === 'sign-agreement') return openSignatureForm();
  if (action === 'verify-signature') return openSignatureReview(source.dataset.signature, 'verified');
  if (action === 'void-signature') return openSignatureReview(source.dataset.signature, 'void');
  if (action === 'clear-signature') return clearSignature();
  if (action === 'leave-feedback') return openFeedbackForm(source.dataset.item);
  if (action === 'leave-project-feedback') return openFeedbackForm();
  if (action === 'review-feedback') return openFeedbackReview(source.dataset.feedback);
  if (action === 'print-report') return printReport();
}

view.addEventListener('click', event => { const source = event.target.closest('[data-action]'); if (source) safely(() => handleAction(source.dataset.action, source)); });
topActions.addEventListener('click', event => { const source = event.target.closest('[data-action]'); if (source) safely(() => handleAction(source.dataset.action, source)); });
modalLayer.addEventListener('click', event => { if (event.target === modalLayer) closeModal(); const source = event.target.closest('[data-action]'); if (source) safely(() => handleAction(source.dataset.action, source)); });
view.addEventListener('input', event => { if (event.target.matches('[data-role="item-search"], [data-role="item-status"]')) applyFilters(); });
modalLayer.addEventListener('change', event => { if (event.target.name === 'proof' && event.target.files?.[0]) { const image = $('proofPreview'); image.src = URL.createObjectURL(event.target.files[0]); image.classList.add('visible'); } });
view.addEventListener('submit', event => { if (event.target.id !== 'loginForm') return; event.preventDefault(); const form = event.target; const button = form.querySelector('button'); safely(async () => { const data = new FormData(form); button.disabled = true; button.textContent = 'Signing in…'; try { await signInWithEmailAndPassword(auth, text(data.get('email')), text(data.get('password'))); } catch (error) { button.disabled = false; button.textContent = 'Sign in securely'; throw error; } }); });

function boot() {
  const params = new URLSearchParams(location.search); const access = params.get('access');
  if (access) { safely(() => loadPublic(access)); return; }
  if (params.get('c') || params.get('view') === 'client') { renderLegacyLink(); return; }
  onAuthStateChanged(auth, user => safely(async () => { state.user = user; if (!user) { renderLogin(); return; } if (user.email !== ADMIN_EMAIL) { await signOut(auth); renderLogin('This account is not allowed to access the admin portal.'); return; } state.mode = 'admin'; await loadPrivateClients(); const clientKey = params.get('c'); const projectKey = params.get('p'); state.clientKey = clientKey && state.clients[clientKey] ? clientKey : null; state.projectKey = projectKey && state.clients[state.clientKey]?.projects?.[projectKey] ? projectKey : null; if (state.projectKey) renderProject(); else if (state.clientKey) renderClient(); else renderDashboard(); }));
}
boot();
